'use strict';
const C=InventoryCore,KEY='jaegoon.inventory.v1',main=document.querySelector('#main'),modal=document.querySelector('#modal');
const paths={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',items:'<path d="m3 7 9-5 9 5v10l-9 5-9-5zM3 7l9 5 9-5M12 12v10M7 4l10 6"/>',moves:'<path d="M4 7h15m-4-4 4 4-4 4M20 17H5m4-4-4 4 4 4"/>',orders:'<path d="M8 4h12v17H4V4h4M8 2h8v4H8zM8 11h8M8 15h6"/>',analysis:'<path d="M4 3v18h17M9 16V9m5 7V5m5 11v-5"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="currentColor"/><circle cx="15" cy="17" r="3" fill="currentColor"/>',backup:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',plus:'<path d="M12 4v16M4 12h16"/>',money:'<rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="12" cy="12" r="3"/>',alert:'<path d="m12 3 10 18H2zM12 9v5m0 3v1"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>'};
const icon=n=>`<svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.items}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=v=>v==null?'—':Number(v).toLocaleString('ko-KR',{maximumFractionDigits:1});
const won=v=>v==null?'확인 필요':'₩'+number(v);
const uuid=()=>crypto.randomUUID?.()||'id-'+Date.now()+'-'+Math.random().toString(16).slice(2);
const blank=()=>({version:1,items:[],movements:[],settings:{...C.defaults}});
let state=blank(),realState=null,demo=false,storageFault=false,rawAtLoad=null,page='dashboard',query='',statusFilter='',categoryFilter='',moveType='',moveFrom='',moveTo='';
try{rawAtLoad=localStorage.getItem(KEY);if(rawAtLoad)state=C.validate(JSON.parse(rawAtLoad));}catch(e){storageFault=true;setTimeout(()=>toast('저장 데이터 읽기 실패: 백업/복원 화면을 확인해 주세요.'),200);}
const menu=[['dashboard','대시보드'],['items','품목 관리'],['moves','입출고 내역'],['orders','발주 관리'],['analysis','재고 분석'],['settings','기준 설정'],['backup','백업 / 복원']];
function commit(next){C.validate(next);if(!demo){if(storageFault)throw Error('저장소 오류 상태입니다. 먼저 원본 데이터를 내려받고 복원해 주세요.');if(localStorage.getItem(KEY)!==rawAtLoad)throw Error('다른 창에서 데이터가 변경되었습니다. 새로고침 후 다시 시도해 주세요.');const raw=JSON.stringify(next);localStorage.setItem(KEY,raw);rawAtLoad=raw;}state=next;}
const clone=()=>structuredClone(state);
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',4200);}
function download(name,body,type='text/plain;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([body],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
const badge=s=>`<span class="badge ${{'정상':'normal','긴급':'urgent','발주 필요':'order','과잉':'excess','확인 필요':'unknown'}[s]||'unknown'}">${s}</span>`;
const rows=()=>state.items.map(p=>({...p,...C.analyze(state,p)}));
const empty=(title,desc,button='')=>`<div class="empty"><div class="empty-icon">${icon('items')}</div><h3>${title}</h3><p>${desc}</p>${button}</div>`;
const btn=(action,label,cls='',data='')=>`<button type="button" class="button ${cls}" data-action="${action}" ${data}>${label}</button>`;
function heading(name,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">INVENTORY WORKSPACE</div><h1>${name}</h1><p class="subtitle">${description}</p></div><div class="actions">${actions}</div></div>`;}
function banner(){return (demo?`<div class="notice demo"><span><b>예시 데이터 체험 중</b> · 아래 값은 가상의 예시이며 실제 데이터에 저장되지 않습니다.</span>${btn('demo-exit','내 데이터로 돌아가기','small')}</div>`:'')+(storageFault?'<div class="error">저장 데이터를 읽지 못했습니다. 원본 보호를 위해 저장을 중지했습니다. 백업 / 복원에서 원본을 다운로드한 후 복원해 주세요.</div>':'');}
function render(){page=location.hash.slice(1)||'dashboard';if(!menu.some(m=>m[0]===page))page='dashboard';document.querySelector('#nav').innerHTML=menu.map(([key,label])=>`<a href="#${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''} title="${label}">${icon(key)}<span class="nav-text">${label}</span>${key==='orders'&&rows().filter(p=>p.recommended>0).length?`<span class="nav-count">${rows().filter(p=>p.recommended>0).length}</span>`:''}</a>`).join('');document.querySelector('#crumb').textContent=menu.find(m=>m[0]===page)[1];document.querySelector('#today').textContent=new Date().toLocaleDateString('ko-KR',{year:'numeric',month:'long',day:'numeric',weekday:'short',timeZone:'Asia/Seoul'});main.innerHTML=banner()+({dashboard:dashboard,items:itemsPage,moves:movesPage,orders:ordersPage,analysis:analysisPage,settings:settingsPage,backup:backupPage}[page])();}
function dashboard(){const rr=rows(),urgent=rr.filter(p=>['긴급','발주 필요'].includes(p.status)),missing=rr.filter(p=>p.price==null).length;const val=rr.reduce((s,p)=>s+(p.value??0),0);const stats=[['등록 품목',number(rr.length),'개',`분류 ${new Set(rr.map(p=>p.category).filter(Boolean)).size}개 · 보관 장소 ${new Set(rr.map(p=>p.location).filter(Boolean)).size}곳`,'items'],['총 재고 금액',won(val),'',missing?`단가 미입력 ${missing}개 제외`:'입력 단가 × 현재고 기준','money'],['발주 확인 품목',number(urgent.length),'개',urgent.length?'부족 재고를 확인해 주세요':'안전재고와 발주점 기준','alert'],['불용 검토 품목',number(rr.filter(p=>p.idle).length),'개',`${state.settings.idleDays}일 이상 출고 없음`,'clock']];
return heading('재고 현황을 한눈에','오늘의 재고를 확인하고, 필요한 다음 작업을 시작하세요.',btn('export','↓ 현황 내보내기')+btn('move',icon('plus')+' 입출고 등록','primary'))+(!demo?`<div class="notice"><span>${icon('items')} <b>기록이 쌓일수록, 관리가 쉬워집니다.</b> ${rr.length?'실제 수량을 바꾸려면 입출고 또는 재고 조정을 등록하세요.':'첫 품목을 등록하거나 예시 데이터로 먼저 둘러보세요.'}</span>${btn('demo','예시 데이터 체험 →','small ghost')}</div>`:'')+`<div class="stats">${stats.map(([l,v,u,n,i],idx)=>`<div class="stat"><div class="stat-label">${l}${icon(i)}</div><div class="stat-value ${idx===2&&urgent.length?'red':''}">${v}<small>${u}</small></div><div class="stat-note ${idx===2&&urgent.length?'red':''}">${n}</div></div>`).join('')}</div><div class="panels"><section class="panel"><div class="panel-head"><h2>발주가 필요한 품목 <span class="count-chip">${urgent.length}</span></h2><a class="text-link" href="#orders">전체 보기 →</a></div>${urgent.length?`<div class="table-wrap"><table><thead><tr><th>품목명</th><th class="num">현재고</th><th class="num">발주점</th><th>상태</th></tr></thead><tbody>${urgent.slice(0,4).map(p=>`<tr><td><div class="item-name">${esc(p.name)}</div><div class="item-code">${esc(p.sku)}</div></td><td class="num ${p.status==='긴급'?'red':''}">${number(p.qty)} <small>${esc(p.unit)}</small></td><td class="num">${number(p.rop)}</td><td>${badge(p.status)}</td></tr>`).join('')}</tbody></table></div>`:rr.length?empty('부족 재고가 없습니다','기준이 입력되지 않은 품목은 품목 관리에서 확인하세요.'): `<div class="big-empty"><div class="empty-icon">${icon('items')}</div><div><h3>첫 번째 품목을 등록해 보세요</h3><p>품목과 현재 수량을 입력하면<br>재고 관리가 시작됩니다.</p>${btn('item','＋ 품목 등록','primary')}</div></div>`}</section><section class="panel"><div class="panel-head"><h2>재고 상태 분포</h2><small>품목 수 기준</small></div>${donut(rr)}</section></div><div class="panels"><section class="panel"><div class="panel-head"><h2>최근 입출고 내역</h2><a class="text-link" href="#moves">전체 보기 →</a></div>${movementTable(state.movements.slice().reverse().slice(0,4),true)}</section><section class="panel"><div class="panel-head"><h2>최근 7일 입출고</h2><small>기록 건수</small></div><div class="panel-body">${weeklyChart()}</div></section></div><section class="panel"><div class="panel-head"><h2>전체 품목 미리보기</h2><a class="text-link" href="#items">품목 관리 →</a></div>${rr.length?itemTable(rr.slice(0,5),true):empty('품목 데이터가 아직 없습니다','직접 등록하거나 CSV 파일을 가져올 수 있습니다.')}</section>`;}
function donut(rr){const colors={'정상':'#679b7c','발주 필요':'#d7b76e','긴급':'#d88373','과잉':'#88a4bc','확인 필요':'#dce3dc'},counts=Object.keys(colors).map(k=>[k,rr.filter(p=>p.status===k).length]);let start=0;const stops=counts.map(([k,n])=>{let prev=start;start+=rr.length?n/rr.length*100:0;return `${colors[k]} ${prev}% ${start}%`;});return `<div class="chart-area"><div class="donut" style="background:${rr.length?`conic-gradient(${stops.join(',')})`:'#eaf0e9'}" role="img" aria-label="총 ${rr.length}개 품목 상태 분포"><div class="donut-center">${rr.length}<small>전체 품목</small></div></div><div class="legend">${counts.map(([k,n])=>`<div class="legend-row"><span class="dot" style="background:${colors[k]}"></span>${k}<b>${n}</b></div>`).join('')}</div></div>`;}
function weeklyChart(){const days=Array.from({length:7},(_,i)=>{const d=new Date(C.today()+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-6+i);const date=d.toISOString().slice(0,10);return {date,in:state.movements.filter(m=>m.date===date&&m.type==='in').length,out:state.movements.filter(m=>m.date===date&&m.type==='out').length};}),max=Math.max(1,...days.flatMap(d=>[d.in,d.out]));return `<div class="bar-list">${days.map(d=>`<div class="bar-day"><div class="bar-pair" title="${d.date} 입고 ${d.in}건 / 출고 ${d.out}건"><span style="height:${d.in/max*100}%"></span><span style="height:${d.out/max*100}%"></span></div>${d.date.slice(5).replace('-','/')}</div>`).join('')}</div><div class="inline-legend"><span><i class="dot" style="background:#6f9e84"></i> 입고</span><span><i class="dot" style="background:#dce8df"></i> 출고</span></div>`;}
function searchField(placeholder){return `<div class="search">${icon('search')}<input id="search" aria-label="검색" placeholder="${placeholder}" value="${esc(query)}"></div>`;}
function itemTable(rr,short=false){if(!rr.length)return empty('조건에 맞는 품목이 없습니다','검색어나 필터를 변경해 주세요.');const grades=C.abc(state);return `<div class="table-wrap"><table><thead><tr><th>품목 / 코드</th><th>분류 · 보관 장소</th><th class="num">현재고</th><th class="num">안전재고</th><th class="num">발주점</th><th>상태</th>${!short?'<th>ABC</th><th></th>':''}</tr></thead><tbody>${rr.map(p=>`<tr><td><div class="item-name">${esc(p.name)}</div><div class="item-code">${esc(p.sku)}</div></td><td>${esc(p.category||'미분류')}<div class="item-code">${esc(p.location||'장소 미입력')}</div></td><td class="num"><b>${number(p.qty)}</b> <small>${esc(p.unit)}</small></td><td class="num">${number(p.safety)}</td><td class="num">${number(p.rop)}</td><td>${badge(p.status)} ${p.idle?'<span class="badge idle">불용 검토</span>':''}</td>${!short?`<td><span class="grade ${grades[p.id].grade}">${grades[p.id].grade}</span></td><td>${btn('item','수정','small',`data-id="${esc(p.id)}"`)} ${btn('move','입출고','small',`data-id="${esc(p.id)}"`)}</td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function filtered(){return rows().filter(p=>(!query||[p.name,p.sku,p.category,p.location,p.supplier].join(' ').toLowerCase().includes(query.toLowerCase()))&&(!statusFilter||(statusFilter==='불용 검토'?p.idle:p.status===statusFilter))&&(!categoryFilter||p.category===categoryFilter));}
function itemsPage(){return heading('품목 관리','품목 정보와 재고 기준을 함께 관리하세요.',`<a class="button" href="./templates/품목_일괄등록_업로드용.csv" download>↓ 업로드 양식</a>`+btn('csv-import','↑ CSV 가져오기')+btn('item','＋ 품목 등록','primary'))+`<section class="panel"><div class="toolbar">${searchField('품목명, 코드, 보관 장소 검색')}<select id="category-filter" aria-label="분류 필터"><option value="">모든 분류</option>${[...new Set(state.items.map(p=>p.category).filter(Boolean))].map(c=>`<option ${c===categoryFilter?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="status-filter" aria-label="상태 필터"><option value="">모든 상태</option>${['정상','긴급','발주 필요','과잉','확인 필요','불용 검토'].map(s=>`<option ${s===statusFilter?'selected':''}>${s}</option>`).join('')}</select>${btn('export','↓ CSV','small')}</div><div id="item-results">${itemTable(filtered())}</div><div class="table-foot"><span id="result-count">전체 ${state.items.length}개 · 검색 결과 ${filtered().length}개</span><span>— : 계산에 필요한 데이터 미입력</span></div></section>`;}
const moveLabel={opening:'초기 재고',in:'입고',out:'출고',adjust:'재고 조정'};
function movementTable(moves,short=false){return moves.length?`<div class="table-wrap"><table><thead><tr><th>일자</th><th>품목명</th><th>유형</th><th class="num">수량 증감</th>${!short?'<th>메모 / 조정 사유</th>':''}</tr></thead><tbody>${moves.map(m=>{const p=state.items.find(i=>i.id===m.itemId);return `<tr><td>${m.date.replaceAll('-','.')}</td><td><span class="item-name">${esc(p?.name||'알 수 없는 품목')}</span><div class="item-code">${esc(p?.sku)}</div></td><td><span class="badge ${m.type==='out'?'excess':m.type==='in'?'normal':'unknown'}">${moveLabel[m.type]}</span></td><td class="num ${m.delta>0?'green':''}">${m.delta>0?'+':''}${number(m.delta)} ${esc(p?.unit)}</td>${!short?`<td style="white-space:normal;min-width:150px">${esc(m.note||'—')}</td>`:''}</tr>`;}).join('')}</tbody></table></div>`:empty('입출고 기록이 없습니다','입출고를 등록하면 이곳에 이력이 쌓입니다.');}
function selectedMoves(){return state.movements.slice().reverse().filter(m=>{const p=state.items.find(i=>i.id===m.itemId);return (!moveType||m.type===moveType)&&(!moveFrom||m.date>=moveFrom)&&(!moveTo||m.date<=moveTo)&&(!query||[p?.name,p?.sku,m.note].join(' ').toLowerCase().includes(query.toLowerCase()));});}
function movesPage(){return heading('입출고 내역','입출고와 실사 조정을 기록하고 이력을 확인하세요.',btn('export-moves','↓ CSV 내보내기')+btn('move','＋ 입출고 등록','primary'))+`<section class="panel"><div class="toolbar">${searchField('품목명, 코드, 메모 검색')}<select id="move-type" aria-label="입출고 구분"><option value="">전체 유형</option>${Object.entries(moveLabel).map(([k,v])=>`<option value="${k}" ${moveType===k?'selected':''}>${v}</option>`).join('')}</select><input id="move-from" aria-label="시작일" type="date" value="${moveFrom}"><span>~</span><input id="move-to" aria-label="종료일" type="date" value="${moveTo}"></div><div id="move-results">${movementTable(selectedMoves())}</div><div class="table-foot">실수로 입력한 수량은 재고 조정으로 바로잡으세요. 기존 이력은 보존됩니다.</div></section>`;}
function ordersPage(){const rr=rows().filter(p=>p.recommended>0);return heading('발주 관리','입고 예정 수량을 반영해 발주 검토 목록을 확인하세요.',btn('export-orders','↓ 발주 목록 CSV','primary'))+`<div class="notice"><span><b>발주 제안 목록입니다.</b> 권장 수량은 목표재고 보충 기준이며, 실제 주문은 거래처에 별도로 진행하세요.</span></div><section class="panel"><div class="panel-head"><h2>발주 검토 목록 <span class="count-chip">${rr.length}</span></h2><small>재고 위치 = 현재고 + 입고 예정</small></div>${rr.length?`<div class="table-wrap"><table><thead><tr><th>품목명</th><th>거래처</th><th class="num">현재고</th><th class="num">입고 예정</th><th class="num">목표재고</th><th class="num">권장 발주량</th><th class="num">예상 금액</th><th></th></tr></thead><tbody>${rr.map(p=>`<tr><td><b>${esc(p.name)}</b><div class="item-code">${esc(p.sku)}</div></td><td>${esc(p.supplier||'확인 필요')}</td><td class="num">${number(p.qty)}</td><td class="num">${number(p.onOrder??0)}</td><td class="num">${number(p.target)}</td><td class="num green"><b>${number(p.recommended)} ${esc(p.unit)}</b></td><td class="num">${p.price==null?'확인 필요':won(p.recommended*p.price)}</td><td>${btn('item','기준 수정','small',`data-id="${esc(p.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('계산된 발주 제안이 없습니다','품목의 출고량, 리드타임, 안전재고 및 목표 보유일수를 확인하세요.')}<div class="table-foot">입고 예정 수량은 직접 관리합니다. 입고 등록 시 예정 수량에서 차감할 수 있습니다.</div></section><div class="help-box"><p>재고 위치 ≤ 발주점이면 권장 발주량 = max(0, 목표재고 − 재고 위치).</p><p>EOQ는 재고 분석에서 별도로 표시합니다. 최소 주문량·포장 단위·예산·예약 출고는 반영하지 않습니다.</p></div>`;}
function analysisPage(){const rr=rows(),grades=C.abc(state);return heading('재고 분석','ABC 등급과 보유일수로 관리 우선순위를 확인하세요.',btn('export','↓ 분석 포함 CSV'))+`<div class="panels"><section class="panel"><div class="panel-head"><h2>ABC 등급 구성</h2><small>일평균 출고 × 30일 × 단가</small></div><div class="panel-body">${['A','B','C'].map(g=>`<div class="formula" style="display:flex;align-items:center;gap:16px"><span class="grade ${g}">${g}</span><div style="flex:1"><b>${g==='A'?'핵심 관리':g==='B'?'일반 관리':'정기 검토'}</b><p>누적 금액 비중 ${g==='A'?`0~${state.settings.abcA}`:g==='B'?`${state.settings.abcA}~${state.settings.abcB}`:`${state.settings.abcB}~100`}% 구간</p></div><b>${rr.filter(p=>grades[p.id].grade===g).length}개</b></div>`).join('')}<p class="mobile-note">합계가 0이거나 단가·평균 출고량이 없으면 미분류(—). 경계를 넘기는 품목은 앞 구간에 포함합니다.</p></div></section><section class="panel"><div class="panel-head"><h2>재고 상태 분포</h2><small>불용 검토는 별도 표시</small></div>${donut(rr)}</section></div><section class="panel"><div class="panel-head"><h2>품목별 분석</h2><small>추정 출고액은 실제 매출액이 아닙니다.</small></div>${rr.length?`<div class="table-wrap"><table><thead><tr><th>품목명</th><th>ABC</th><th class="num">재고 금액</th><th class="num">보유일수</th><th class="num">EOQ</th><th>최근 출고 / 관찰 시작</th><th>상태</th></tr></thead><tbody>${rr.sort((a,b)=>(b.daily??0)*(b.price??0)-(a.daily??0)*(a.price??0)).map(p=>`<tr><td><b>${esc(p.name)}</b><div class="item-code">${esc(p.sku)}</div></td><td><span class="grade ${grades[p.id].grade}">${grades[p.id].grade}</span><div class="item-code">${number(grades[p.id].share)}%</div></td><td class="num">${won(p.value)}</td><td class="num">${number(p.days)}${p.days!=null?'일':''}</td><td class="num">${number(p.eoq)}</td><td>${p.last}</td><td>${badge(p.status)} ${p.idle?'<span class="badge idle">불용 검토</span>':''}</td></tr>`).join('')}</tbody></table></div>`:empty('분석할 품목이 없습니다','품목을 등록하고 기준 정보를 입력해 주세요.')}</section><div class="help-box">불용 검토는 자동 폐기 판정이 아닙니다. 출고 이력이 없으면 등록일 또는 직접 입력한 최종 출고일부터 관찰하며, ${state.settings.idleDays}일 이상 출고가 없고 재고가 있을 때 표시합니다.</div>`;}
function field(name,label,value='',type='number',help='',required=false){return `<label class="field">${label}${required?' *':''}<input name="${name}" type="${type}" ${type==='number'?'min="0" max="1000000000000" step="any"':''} ${type==='date'?`max="${C.today()}"`:''} ${type==='text'?'maxlength="300"':''} value="${esc(value??'')}" ${required?'required':''}>${help?`<small>${help}</small>`:''}</label>`;}
function settingsPage(){return heading('기준 설정','관리 정책과 계산식을 확인하고, 업무에 맞는 기준을 설정하세요.')+`<div class="setting-grid"><section class="panel"><div class="panel-head"><h2>공통 관리 정책</h2></div><form id="settings-form"><div class="panel-body"><div id="settings-error" class="error"></div><div class="form-grid">${field('abcA','ABC · A 구간 상한 (%)',state.settings.abcA,'number','초기 정책 80% · 변경 가능',true)}${field('abcB','ABC · B 구간 상한 (%)',state.settings.abcB,'number','초기 정책 95% · 변경 가능',true)}${field('idleDays','불용 검토 기준 (일)',state.settings.idleDays,'number','초기 정책 90일 · 1~3,650일',true)}</div><div class="help-box">이 값은 프로그램의 초기 관리 정책이며 사용자의 실제 수요 데이터가 아닙니다. 안전재고·리드타임·목표일수는 품목별로 입력해 주세요.</div><button class="button primary">기준 저장</button></div></form></section><section class="panel"><div class="panel-head"><h2>재고 계산 기준</h2></div><div class="panel-body"><div class="formula"><h3>01 · 안전재고</h3><p>품목별로 두 방법 중 하나를 선택합니다.</p><code>일수 방식 = 일평균 출고량 × 완충일수<br>최대 방식 = max(0, 최대 일출고량 × 최대 리드타임 − 일평균 출고량 × 평균 리드타임)</code></div><div class="formula"><h3>02 · 발주점과 목표재고</h3><code>발주점 = 일평균 출고량 × 평균 리드타임 + 안전재고<br>목표재고 = 일평균 출고량 × 목표 보유일수 + 안전재고</code><p>목표 보유일수는 평균 리드타임 이상. 계산 수량은 올림합니다.</p></div><div class="formula"><h3>03 · 재고 상태</h3><p>긴급: 현재고 ≤ 안전재고<br>발주 필요: 안전재고 &lt; 현재고 ≤ 발주점<br>정상: 발주점 &lt; 현재고 ≤ 목표재고<br>과잉: 현재고 &gt; 목표재고<br>세 기준 중 누락이 있으면 ‘확인 필요’</p></div><div class="formula"><h3>04 · 경제적 주문량 (EOQ)</h3><code>√(2 × 연간 수요 × 1회 발주비 ÷ 단위당 연간 보유비)</code><p>보유비가 0이거나 필수 값이 없으면 계산하지 않습니다. 일정한 수요·리드타임을 전제로 한 참고치이며 권장 발주량과 별개입니다.</p></div></div></section></div>`;}
function backupPage(){return heading('백업 / 복원','기록을 파일로 보관하고 필요할 때 다시 불러오세요.')+`<div class="setting-grid"><section class="panel"><div class="panel-head"><h2>전체 데이터 백업</h2>${icon('backup')}</div><div class="panel-body"><p class="subtitle">품목 ${state.items.length}개 · 입출고 ${state.movements.length}건 · 관리 기준</p><div class="help-box">브라우저 기록 삭제나 기기 변경 전에 JSON 백업을 저장하세요. CSV는 보고용이며 전체 이력을 복원하지 않습니다.</div>${btn('backup','↓ JSON 백업 저장','primary')}${storageFault?btn('raw-backup','읽지 못한 원본 다운로드','danger'):''}</div></section><section class="panel"><div class="panel-head"><h2>JSON 백업 복원</h2></div><div class="panel-body"><p class="subtitle">재고온에서 만든 백업 파일을 불러옵니다.</p><div class="help-box">파일 검증 후 품목·이력 수를 보여드립니다. 복원하면 현재 데이터가 교체되므로 먼저 백업하세요.</div>${btn('restore','↑ 백업 파일 선택')}</div></section><section class="panel"><div class="panel-head"><h2>CSV로 품목 추가</h2></div><div class="panel-body"><p class="subtitle">첨부 양식 또는 기본 빈 양식을 내려받아 작성한 뒤 품목을 일괄 추가하세요. 첨부 양식에는 입력된 품목 3개가 포함되어 있으므로 사용 전 내용을 확인하세요.</p><div class="help-box">필수 열: 품목코드, 품목명, 현재고, 단위<br>기존 코드와 중복되는 행은 가져오지 않습니다. 전체 파일을 검증한 뒤 한 번에 저장합니다.</div><div class="actions">${btn('template','↓ 기본 빈 양식')}<a class="button" href="./templates/품목_일괄등록_업로드용.csv" download>↓ 첨부 업로드 양식 (3개 품목 포함)</a>${btn('csv-import','↑ CSV 가져오기')}</div></div></section><section class="panel"><div class="panel-head"><h2>프로그램과 사용 안내</h2></div><div class="panel-body"><p class="subtitle">설치 없이 이용하는 개인용 프로그램입니다.</p><div class="help-box">데이터는 현재 브라우저에만 저장됩니다. 다른 기기나 여러 사용자가 자동으로 공유하지 않습니다. 발주 제안은 실제 거래처로 전송되지 않습니다.</div><div class="actions"><a class="button" href="./재고온_소스코드.zip" download>↓ GitHub 배포용 전체 소스</a><a class="button" href="./README.md" download>↓ 사용·배포 안내</a></div></div></section></div>`;}
function openDialog(title,subtitle,body,foot='',form=''){document.querySelector('#modal-body').innerHTML=`<div class="modal-head"><div><h2>${title}</h2><p class="subtitle">${subtitle}</p></div><button class="close" data-action="close" aria-label="닫기">×</button></div>${form?`<form id="${form}">`:''}<div class="modal-content"><div id="modal-error" class="error" role="alert"></div>${body}</div>${foot?`<div class="modal-foot">${btn('close','취소')}${foot}</div>`:''}${form?'</form>':''}`;modal.showModal();}
function itemDialog(id){const p=state.items.find(p=>p.id===id)||{method:'days',unit:'개'};openDialog(id?'품목 정보 수정':'새 품목 등록','* 필수 항목 · 빈 숫자 항목은 확인 필요로 남겨 둡니다.',`<input type="hidden" name="id" value="${esc(id||'')}"><div class="form-grid">${field('sku','품목코드',p.sku,'text','예: OFF-001',true)}${field('name','품목명',p.name,'text','',true)}${field('category','분류',p.category,'text')}${field('unit','단위',p.unit,'text','예: 개, 박스, 권',true)}${field('location','보관 장소',p.location,'text')}${field('supplier','거래처',p.supplier,'text')}${field('price','단가 (원)',p.price)}${id?`<div class="field">현재고<strong>${number(C.stock(state,id))} ${esc(p.unit)}</strong><small>수량 변경은 입출고 등록에서 하세요.</small></div>`:field('opening','현재고',0,'number','0 이상의 정수',true)}<div class="form-section">재고 기준 · 입력한 값으로만 계산합니다</div><label class="field">안전재고 방식<select name="method"><option value="days" ${p.method==='days'?'selected':''}>일수 방식 (평균 출고 × 완충일)</option><option value="max" ${p.method==='max'?'selected':''}>최대 출고·리드타임 방식</option></select></label>${field('daily','일평균 출고량',p.daily,'number','소수 입력 가능')}${field('lead','평균 리드타임 (일)',p.lead)}${field('bufferDays','완충일수 · 일수 방식',p.bufferDays)}${field('maxDaily','최대 일출고량 · 최대 방식',p.maxDaily)}${field('maxLead','최대 리드타임 · 최대 방식 (일)',p.maxLead)}${field('targetDays','목표 보유일수',p.targetDays,'number','평균 리드타임 이상')}${field('onOrder','입고 예정 수량',p.onOrder,'number','미입력 시 예정 없음(0)으로 처리')}${field('lastOut','기존 최종 출고일',p.lastOut,'date','기존 이력이 있을 때 입력')}<div class="form-section">선택 입력 · EOQ 계산</div>${field('annual','연간 수요량',p.annual)}${field('orderCost','1회 발주 비용 (원)',p.orderCost)}${field('holding','단위당 연간 보유 비용 (원)',p.holding)}</div>`, '<button class="button primary" type="submit">품목 저장</button>','item-form');}
function moveDialog(id){if(!state.items.length){toast('먼저 품목을 등록해 주세요.');itemDialog();return;}const p=state.items.find(p=>p.id===id)||state.items[0];openDialog('입출고 등록','수량 변경은 이력으로 남으며, 현재고를 초과한 출고는 차단합니다.',`<div class="form-grid"><label class="field span-2">품목 *<select name="itemId" id="movement-item">${state.items.map(i=>`<option value="${esc(i.id)}" ${p.id===i.id?'selected':''}>${esc(i.name)} (${esc(i.sku)})</option>`).join('')}</select></label><div class="help-box span-2" id="current-qty" style="margin:0">현재고: <b>${number(C.stock(state,p.id))} ${esc(p.unit)}</b> · 입고 예정 ${number(p.onOrder??0)}</div><label class="field">유형 *<select name="type" id="movement-type"><option value="in">입고</option><option value="out">출고</option><option value="adjust">재고 조정 (실사)</option></select></label>${field('date','일자',C.today(),'date','',true)}${field('quantity','수량',null,'number','조정 시 실사한 최종 수량을 입력',true)}<label class="field" style="justify-content:center"><span><input style="width:auto" type="checkbox" name="deduct" checked> 입고 예정 수량에서 차감</span><small>입고일 때만 적용, 0 미만으로 차감하지 않음</small></label><label class="field span-2">메모 / 조정 사유<textarea name="note" maxlength="1000" placeholder="사용 부서, 입고 사유 등을 남겨주세요. 조정 시 필수입니다."></textarea></label></div>`,'<button type="submit" class="button primary">등록하기</button>','move-form');}
function demoState(){const s=blank(),date=C.today();const prior=n=>{const d=new Date(date+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-n);return d.toISOString().slice(0,10);};const samples=[['OFF-001','A4 복사용지','사무용품','박스','창고 A-01',125,22000,12,7,5,21,'오피스파트너'],['OFF-002','검정 볼펜 0.5mm','사무용품','개','창고 A-02',18,1200,7,5,4,20,'오피스파트너'],['PKG-001','택배 박스 M','포장자재','개','창고 B-01',340,800,15,5,3,20,'패키지웍스'],['PKG-002','포장용 테이프','포장자재','개','창고 B-02',32,2400,8,4,3,14,'패키지웍스'],['CLN-001','핸드워시 리필','생활용품','개','보관실 C-01',76,4500,2,5,3,20,'클린스토어'],['OFF-003','클리어 파일 A4','사무용품','개','창고 A-03',120,900,3,7,4,35,'오피스파트너'],['CLN-002','쓰레기봉투 50L','생활용품','묶음','보관실 C-02',45,8000,1,3,3,30,'클린스토어'],['OFF-004','문서 보관 상자','사무용품','개','창고 A-04',15,3500,null,null,null,null,'오피스파트너']];
 samples.forEach((x,i)=>{const [sku,name,category,unit,location,qty,price,daily,lead,bufferDays,targetDays,supplier]=x,p={id:'demo-'+i,sku,name,category,unit,location,price,daily,lead,bufferDays,targetDays,supplier,method:'days',maxDaily:null,maxLead:null,onOrder:0,annual:daily==null?null:daily*365,orderCost:15000,holding:price*.2,created:prior(120),lastOut:i===4?prior(100):prior(2)};s.items.push(p);s.movements.push({id:'demo-opening-'+i,itemId:p.id,type:'opening',delta:qty,date:prior(120),note:'가상의 예시 데이터',createdAt:new Date().toISOString()});});
 for(let i=0;i<7;i++){const id='demo-'+i%4;for(const [j,type,delta] of [[0,'in',10+i],[1,'out',-(10+i)]])s.movements.push({id:`demo-m-${i}-${j}`,itemId:id,type,delta,date:prior(6-i),note:type==='in'?'정기 입고 · 예시':'부서 사용 · 예시',createdAt:new Date().toISOString()});}return C.validate(s);}
const exportHeaders=C.columns;
function exportItems(){const grades=C.abc(state);download('재고온_재고현황_'+C.today()+'.csv',C.csv([[...exportHeaders,'안전재고','발주점','목표재고','상태','불용검토','권장발주량','ABC','EOQ'],...rows().map(p=>[p.sku,p.name,p.category,p.unit,p.location,p.supplier,p.qty,p.price,p.daily,p.lead,p.bufferDays,p.targetDays,p.maxDaily,p.maxLead,p.method,p.onOrder,p.annual,p.orderCost,p.holding,p.last,p.safety,p.rop,p.target,p.status,p.idle?'검토 필요':'',p.recommended,grades[p.id].grade,p.eoq])]),'text/csv;charset=utf-8');}
function filePick(mode){const input=document.querySelector('#file-input');input.accept=mode==='restore'?'.json':'.csv';input.value='';input.onchange=async()=>{try{const f=input.files[0];if(!f)return;if(f.size>10*1024*1024)throw Error('10MB 이하 파일을 선택해 주세요.');const txt=await f.text();if(mode==='restore'){const next=C.validate(JSON.parse(txt));openDialog('백업 복원 확인','현재 데이터를 교체합니다.',`<p>품목 <b>${next.items.length}개</b>, 입출고 <b>${next.movements.length}건</b>을 확인했습니다.</p><p class="subtitle">복원 전 현재 데이터를 백업해 두세요.</p>`,btn('backup','현재 데이터 백업')+btn('confirm-restore','교체하여 복원','primary'));document.querySelector('[data-action="confirm-restore"]').onclick=()=>{try{if(storageFault&&!demo){const raw=JSON.stringify(next);localStorage.setItem(KEY,raw);rawAtLoad=raw;state=next;storageFault=false;}else commit(next);modal.close();render();toast('백업을 복원했습니다.');}catch(e){document.querySelector('#modal-error').textContent=e.message;}};}else previewCSV(txt);}catch(e){toast(e.message);}};input.click();}
function previewCSV(txt){const result=C.importItemsCSV(state,txt),next=result.state,data={length:result.count};
 openDialog('CSV 가져오기 확인','검증된 품목을 기존 데이터에 추가합니다.',`<p><b>${data.length}개</b>의 새 품목을 추가할 준비가 되었습니다.</p><div class="table-wrap"><table><thead><tr><th>품목코드</th><th>품목명</th><th>현재고</th></tr></thead><tbody>${next.items.slice(state.items.length,state.items.length+5).map(p=>`<tr><td>${esc(p.sku)}</td><td>${esc(p.name)}</td><td>${number(C.stock(next,p.id))}</td></tr>`).join('')}</tbody></table></div>${data.length>5?'<p class="subtitle">처음 5개 품목만 미리 보여드립니다.</p>':''}`,btn('confirm-csv','품목 추가','primary'));document.querySelector('[data-action="confirm-csv"]').onclick=()=>{try{commit(next);modal.close();render();toast(`${data.length}개 품목을 추가했습니다.`);}catch(e){document.querySelector('#modal-error').textContent=e.message;}};
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;try{if(a==='close')modal.close();else if(a==='item')itemDialog(b.dataset.id);else if(a==='move')moveDialog(b.dataset.id);else if(a==='demo'){realState=state;state=demoState();demo=true;render();}else if(a==='demo-exit'){state=realState;realState=null;demo=false;render();}else if(a==='backup')download(`재고온_${demo?'예시_':''}백업_${C.today()}.json`,JSON.stringify(state,null,2),'application/json');else if(a==='raw-backup')download('재고온_읽기실패_원본.txt',rawAtLoad||'원본 데이터 없음');else if(a==='export')exportItems();else if(a==='restore'||a==='csv-import')filePick(a);else if(a==='template')download('재고온_품목등록_양식.csv',C.csv([exportHeaders]),'text/csv;charset=utf-8');else if(a==='export-moves')download('재고온_입출고_'+C.today()+'.csv',C.csv([['일자','품목코드','품목명','유형','수량증감','메모'],...selectedMoves().map(m=>{const p=state.items.find(p=>p.id===m.itemId);return [m.date,p.sku,p.name,moveLabel[m.type],m.delta,m.note];})]),'text/csv;charset=utf-8');else if(a==='export-orders')download('재고온_발주제안_'+C.today()+'.csv',C.csv([['품목코드','품목명','거래처','현재고','입고예정','발주점','목표재고','권장발주량','예상금액'],...rows().filter(p=>p.recommended>0).map(p=>[p.sku,p.name,p.supplier,p.qty,p.onOrder??0,p.rop,p.target,p.recommended,p.price==null?'확인 필요':p.price*p.recommended])]),'text/csv;charset=utf-8');}catch(e){toast(e.message);}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,fd=new FormData(form);try{const next=clone();if(form.getAttribute('id')==='item-form'){const id=fd.get('id'),existing=next.items.find(p=>p.id===id),p={id:id||uuid(),created:existing?.created||C.today()};for(const key of ['sku','name','category','unit','location','supplier','method','lastOut'])p[key]=fd.get(key).trim();for(const key of C.numeric){const value=fd.get(key);p[key]=value===''?null:Number(value);}C.validateItem(p);if(existing)next.items[next.items.indexOf(existing)]=p;else{const q=Number(fd.get('opening'));if(!Number.isSafeInteger(q)||q<0)throw Error('초기 재고는 0 이상의 정수여야 합니다.');next.items.push(p);next.movements.push({id:uuid(),itemId:p.id,type:'opening',delta:q,date:C.today(),note:'품목 등록 · 초기 재고',createdAt:new Date().toISOString()});}commit(next);modal.close();render();toast('품목을 저장했습니다.');}else if(form.getAttribute('id')==='move-form'){const m=C.movement(next,{itemId:fd.get('itemId'),type:fd.get('type'),date:fd.get('date'),quantity:Number(fd.get('quantity')),note:fd.get('note').trim()});next.movements.push(m);if(m.type==='in'&&fd.get('deduct')){const p=next.items.find(p=>p.id===m.itemId);p.onOrder=Math.max(0,(p.onOrder??0)-m.delta);}commit(next);modal.close();render();toast('입출고를 등록했습니다.');}else if(form.getAttribute('id')==='settings-form'){next.settings={abcA:Number(fd.get('abcA')),abcB:Number(fd.get('abcB')),idleDays:Number(fd.get('idleDays'))};commit(next);render();toast('관리 기준을 저장했습니다.');}}catch(err){const target=document.querySelector(form.getAttribute('id')==='settings-form'?'#settings-error':'#modal-error');if(target)target.textContent=err.message;else toast(err.message);}});
function filterRender(){if(page==='items'){document.querySelector('#item-results').innerHTML=itemTable(filtered());document.querySelector('#result-count').textContent=`전체 ${state.items.length}개 · 검색 결과 ${filtered().length}개`;}else if(page==='moves')document.querySelector('#move-results').innerHTML=movementTable(selectedMoves());}
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;filterRender();}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='category-filter'){categoryFilter=t.value;filterRender();}if(t.id==='status-filter'){statusFilter=t.value;filterRender();}if(t.id==='move-type'){moveType=t.value;filterRender();}if(t.id==='move-from'){moveFrom=t.value;filterRender();}if(t.id==='move-to'){moveTo=t.value;filterRender();}if(t.id==='movement-item'){const p=state.items.find(p=>p.id===t.value);document.querySelector('#current-qty').textContent=`현재고: ${number(C.stock(state,p.id))} ${p.unit} · 입고 예정 ${number(p.onOrder??0)}`;}});
window.addEventListener('hashchange',()=>{query='';render();});window.addEventListener('storage',e=>{if(e.key===KEY)toast('다른 창에서 변경되었습니다. 새로고침해 주세요.');});render();
